hardware_interface::CallbackReturn MyHwSystem::on_init(
  const hardware_interface::HardwareComponentInterfaceParams & params)
{
  if (
    hardware_interface::SystemInterface::on_init(params) !=
    hardware_interface::CallbackReturn::SUCCESS)
  {
    return hardware_interface::CallbackReturn::ERROR;
  }

  const auto & info = get_hardware_info();
  hw_position_commands_.resize(info.joints.size(), 0.0);
  hw_position_states_.resize(info.joints.size(), 0.0);
  hw_velocity_states_.resize(info.joints.size(), 0.0);

  return hardware_interface::CallbackReturn::SUCCESS;
}

hardware_interface::CallbackReturn MyHwSystem::on_configure(
  const rclcpp_lifecycle::State & /*previous_state*/)
{
  const auto & info = get_hardware_info();
  for (size_t i = 0; i < info.joints.size(); ++i)
  {
    hw_position_commands_[i] = 0.0;
    hw_position_states_[i] = 0.0;
    hw_velocity_states_[i] = 0.0;
  }
  return hardware_interface::CallbackReturn::SUCCESS;
}

hardware_interface::CallbackReturn MyHwSystem::on_activate(
  const rclcpp_lifecycle::State & /*previous_state*/)
{
  // Seed the command with the current state so activation does not cause a jump.
  const auto & info = get_hardware_info();
  for (size_t i = 0; i < info.joints.size(); ++i)
  {
    hw_position_commands_[i] = hw_position_states_[i];
  }
  return hardware_interface::CallbackReturn::SUCCESS;
}

hardware_interface::CallbackReturn MyHwSystem::on_deactivate(
  const rclcpp_lifecycle::State & /*previous_state*/)
{
  return hardware_interface::CallbackReturn::SUCCESS;
}

hardware_interface::return_type MyHwSystem::read(
  const rclcpp::Time & /*time*/, const rclcpp::Duration & period)
{
  const auto & info = get_hardware_info();
  const double dt = period.seconds();
  for (size_t i = 0; i < info.joints.size(); ++i)
  {
    const double previous_position = hw_position_states_[i];
    const double new_position = hw_position_commands_[i];
    hw_velocity_states_[i] = dt > 0.0 ? (new_position - previous_position) / dt : 0.0;
    hw_position_states_[i] = new_position;

    set_state(info.joints[i].name + "/" + hardware_interface::HW_IF_POSITION, hw_position_states_[i]);
    set_state(info.joints[i].name + "/" + hardware_interface::HW_IF_VELOCITY, hw_velocity_states_[i]);
  }
  RCLCPP_INFO_THROTTLE(
    get_logger(), *get_clock(), 1000, "read(): joint_a pos=%f joint_b pos=%f",
    hw_position_states_.size() > 0 ? hw_position_states_[0] : -1.0,
    hw_position_states_.size() > 1 ? hw_position_states_[1] : -1.0);
  return hardware_interface::return_type::OK;
}

hardware_interface::return_type MyHwSystem::write(
  const rclcpp::Time & /*time*/, const rclcpp::Duration & /*period*/)
{
  const auto & info = get_hardware_info();
  for (size_t i = 0; i < info.joints.size(); ++i)
  {
    // Command interfaces default to NaN until a controller has actually claimed and
    // published a value; ignore NaN so we keep tracking the last commanded position.
    const double command =
      get_command<double>(info.joints[i].name + "/" + hardware_interface::HW_IF_POSITION);
    if (!std::isnan(command))
    {
      hw_position_commands_[i] = command;
    }
  }
  return hardware_interface::return_type::OK;
}

}  // namespace my_hw

